/*
    イベント設定画面で設定した値の取得
*/

    const iomInv = aras.IomInnovator;

debugger;
    // フォーム上のチェックボックスを取得
    var elements = document.querySelectorAll('input');
    var strEvents = [];
    for (var i = 0; i < elements.length; i++) {

        var ele = elements[i];
        var eleName = ele.name;
        
        if (ele.type != "checkbox") {
            continue;       // チェックボックス以外は処理対象外
        }
        
        // チェックしてあるチェックボックスを取得
        if (! ele.checked) {
            continue;
        }
        
        strEvents.push(ele.id);
    }

    // ダイアログクローズ処理（カンマ[,]区切り文字列生成、0: チェックしたイベント
    parent.dialogArguments.dialog.close(strEvents);

return;
